//go:build linux && amd64

package sys

import "fmt"

// This whole file is dropped unless GOOS=linux AND GOARCH=amd64.
// Because it never enters the build otherwise, it may safely call
// APIs that only exist on linux/amd64.
func Report() {
	fmt.Println("compiled for linux/amd64") // prints only in that build
}

// file: clock_darwin.go
// The _darwin suffix acts as an implicit //go:build darwin constraint,
// so this file compiles ONLY on macOS — no comment directive needed.

package clock

import "time"

// now() has a macOS-specific implementation selected purely by filename.
func now() time.Time {
	return time.Now() // on GOOS=darwin this is the chosen definition
}

//go:build (linux || darwin) && !cgo

package netpoll

import "fmt"

// Included on Linux OR macOS, but only when cgo is disabled.
// linux && darwin can never both be true, so parentheses + || are required.
func mode() {
	fmt.Println("pure-Go poller on a unix-like OS") // no cgo path here
}

//go:build debug

package app

// Build with: go build -tags=debug
// Without the tag this file is dropped, so trace() does not exist in the
// production binary at all — the diagnostics simply cannot ship.
import "log"

func trace(msg string) {
	log.Printf("[trace] %s", msg) // only present in -tags=debug builds
}

//go:build go1.21

package mathutil

// Included only with Go 1.21+, where the builtin min() exists.
// A sibling file //go:build !go1.21 would supply a hand-rolled fallback.
func smaller(a, b int) int {
	return min(a, b) // uses the Go 1.21 builtin; older Go needs the fallback
}

package main

import (
	"fmt"
	"runtime"
)

func main() {
	// runtime.GOOS: BOTH branches must compile and ship in the binary.
	// Use build tags instead when a branch needs OS-only APIs.
	if runtime.GOOS == "windows" {
		fmt.Println("\\r\\n") // decided at runtime, not compile time
	} else {
		fmt.Println("\\n")
	}
}

// file: hash_cgo.go
//go:build cgo && !purego

package hash

// C-accelerated path, compiled when cgo is enabled and purego is NOT set.
func backend() string { return "cgo-accelerated" }

